SUBROUTINE DIR_TRANSAD(PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, PSPSC3B, PSPSC2, KPROMA, KVSETUV, &
  &                    KVSETSC, KRESOL, KVSETSC3A, KVSETSC3B, KVSETSC2, PGP, PGPUV, PGP3A, PGP3B, &
  &                    PGP2)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE DIR_TRANSAD_CPP_BINDING_SP(ARGS, KPROMA, KRESOL, PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, &
  &                                   PSPSC3B, PSPSC2, KVSETUV, KVSETSC, KVSETSC3A, KVSETSC3B, &
  &                                   KVSETSC2, PGP, PGPUV, PGP3A, PGP3B, PGP2) &
  &                                   BIND(C, NAME="dir_transad_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)    :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KRESOL
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPVOR(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPDIV(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPSCALAR(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPSC3A(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPSC3B(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(INOUT) :: PSPSC2(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETUV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC3A(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC3B(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC2(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT)   :: PGP(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT)   :: PGPUV(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT)   :: PGP3A(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT)   :: PGP3B(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT)   :: PGP2(*)
END SUBROUTINE DIR_TRANSAD_CPP_BINDING_SP
SUBROUTINE DIR_TRANSAD_CPP_BINDING_DP(ARGS, KPROMA, KRESOL, PSPVOR, PSPDIV, PSPSCALAR, PSPSC3A, &
  &                                   PSPSC3B, PSPSC2, KVSETUV, KVSETSC, KVSETSC3A, KVSETSC3B, &
  &                                   KVSETSC2, PGP, PGPUV, PGP3A, PGP3B, PGP2) &
  &                                   BIND(C, NAME="dir_transad_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE INV_DIR_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)    :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KRESOL
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPVOR(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPDIV(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPSCALAR(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPSC3A(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPSC3B(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(INOUT) :: PSPSC2(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETUV(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC3A(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC3B(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KVSETSC2(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT)   :: PGP(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT)   :: PGPUV(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT)   :: PGP3A(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT)   :: PGP3B(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT)   :: PGP2(*)
END SUBROUTINE DIR_TRANSAD_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPVOR(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPDIV(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPSCALAR(:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPSC3A(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPSC3B(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(INOUT) :: PSPSC2(:,:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KPROMA
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KVSETUV(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KVSETSC(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KRESOL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KVSETSC3A(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KVSETSC3B(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KVSETSC2(:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT)   :: PGP(:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT)   :: PGPUV(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT)   :: PGP3A(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT)   :: PGP3B(:,:,:,:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT)   :: PGP2(:,:,:)

TYPE(ARGS_INFO) :: ARGS

! C-interoperable handles for the optional scalar arguments. A null C pointer indicates the
! argument was not present in the Fortran call; otherwise the pointer targets a local temporary.
TYPE(C_PTR) :: KPROMA_PTR, KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IPROMA, IRESOL

ARGS = ARGS_INFO(PSPVOR=PSPVOR, PSPDIV=PSPDIV, PSPSCALAR=PSPSCALAR, PSPSC3A=PSPSC3A, &
  &              PSPSC3B=PSPSC3B, PSPSC2=PSPSC2, KVSETUV=KVSETUV, KVSETSC=KVSETSC, &
  &              KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, KVSETSC2=KVSETSC2, PGP=PGP, &
  &              PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, PGP2=PGP2)

IF (PRESENT(KPROMA)) THEN
  IPROMA = KPROMA
  KPROMA_PTR = C_LOC(IPROMA)
ELSE
  KPROMA_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL DIR_TRANSAD_CPP_BINDING_SP(ARGS, KPROMA_PTR, KRESOL_PTR, PSPVOR=PSPVOR, PSPDIV=PSPDIV, &
  &                             PSPSCALAR=PSPSCALAR, PSPSC3A=PSPSC3A, PSPSC3B=PSPSC3B, &
  &                             PSPSC2=PSPSC2, KVSETUV=KVSETUV, KVSETSC=KVSETSC, &
  &                             KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, KVSETSC2=KVSETSC2, &
  &                             PGP=PGP, PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, PGP2=PGP2)
#else
CALL DIR_TRANSAD_CPP_BINDING_DP(ARGS, KPROMA_PTR, KRESOL_PTR, PSPVOR=PSPVOR, PSPDIV=PSPDIV, &
  &                             PSPSCALAR=PSPSCALAR, PSPSC3A=PSPSC3A, PSPSC3B=PSPSC3B, &
  &                             PSPSC2=PSPSC2, KVSETUV=KVSETUV, KVSETSC=KVSETSC, &
  &                             KVSETSC3A=KVSETSC3A, KVSETSC3B=KVSETSC3B, KVSETSC2=KVSETSC2, &
  &                             PGP=PGP, PGPUV=PGPUV, PGP3A=PGP3A, PGP3B=PGP3B, PGP2=PGP2)
#endif

END SUBROUTINE DIR_TRANSAD
